export type ParsedRetireAccountsV3Instruction<
  TProgram extends string = typeof CLEARING_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    venue: TAccountMetas[0];
    custody: TAccountMetas[1];
    safety: TAccountMetas[2];
    btc: TAccountMetas[3];
    eth: TAccountMetas[4];
    btcLedger: TAccountMetas[5];
    ethLedger: TAccountMetas[6];
    vault: TAccountMetas[7];
    authority: TAccountMetas[8];
    registry: TAccountMetas[9];
    certificate?: TAccountMetas[10] | undefined;
    resolution?: TAccountMetas[11] | undefined;
    eventAuthority: TAccountMetas[12];
    program: TAccountMetas[13];
  };
  data: RetireAccountsV3InstructionData;
};

export function parseRetireAccountsV3Instruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRetireAccountsV3Instruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 14) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 14,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === CLEARING_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      venue: getNextAccount(),
      custody: getNextAccount(),
      safety: getNextAccount(),
      btc: getNextAccount(),
      eth: getNextAccount(),
      btcLedger: getNextAccount(),
      ethLedger: getNextAccount(),
      vault: getNextAccount(),
      authority: getNextAccount(),
      registry: getNextAccount(),
      certificate: getNextOptionalAccount(),
      resolution: getNextOptionalAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getRetireAccountsV3InstructionDataDecoder().decode(instruction.data),
  };
}
